// Generic result status of NearbyConnections API calls.
type ConnectionLayerStatus int32

const (
	// No status is available
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_UNKNOWN ConnectionLayerStatus = 0
	// The operation was successful.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_SUCCESS ConnectionLayerStatus = 1
	// The operation failed, without any more information.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ERROR ConnectionLayerStatus = 2
	// The app called an API method out of order (i.e. another method is expected
	// to be called first).
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_OUT_OF_ORDER_API_CALL ConnectionLayerStatus = 3
	// The app already has active operations (advertising, discovering, or
	// connected to other devices) with another Strategy. Stop these operations on
	// the current Strategy before trying to advertise or discover with a new
	// Strategy.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ALREADY_HAVE_ACTIVE_STRATEGY ConnectionLayerStatus = 4
	// The app is already advertising; call StopAdvertising() before trying to
	// advertise again.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ALREADY_ADVERTISING ConnectionLayerStatus = 5
	// The app is already discovering; call StopDiscovery() before trying to
	// discover again.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ALREADY_DISCOVERING ConnectionLayerStatus = 6
	// NC is already listening for incoming connections from remote endpoints.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ALREADY_LISTENING ConnectionLayerStatus = 7
	// An attempt to read from/write to a connected remote endpoint failed. If
	// this occurs repeatedly, consider invoking DisconnectFromEndpoint().
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_END_POINT_IO_ERROR ConnectionLayerStatus = 8
	// An attempt to interact with a remote endpoint failed because it's unknown
	// to us -- it's either an endpoint that was never discovered, or an endpoint
	// that never connected to us (both of which are indicative of bad input from
	// the client app).
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_END_POINT_UNKNOWN ConnectionLayerStatus = 9
	// The remote endpoint rejected the connection request.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_CONNECTION_REJECTED ConnectionLayerStatus = 10
	// The app is already connected to the specified endpoint. Multiple
	// connections to a remote endpoint cannot be maintained simultaneously.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_ALREADY_CONNECTED_TO_END_POINT ConnectionLayerStatus = 11
	// The remote endpoint is not connected; messages cannot be sent to it.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_NOT_CONNECTED_TO_END_POINT ConnectionLayerStatus = 12
	// There was an error trying to use the device's Bluetooth capabilities.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_BLUETOOTH_ERROR ConnectionLayerStatus = 13
	// There was an error trying to use the device's Bluetooth Low Energy
	// capabilities.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_BLE_ERROR ConnectionLayerStatus = 14
	// There was an error trying to use the device's Wi-Fi capabilities.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_WIFI_LAN_ERROR ConnectionLayerStatus = 15
	// An attempt to interact with an in-flight Payload failed because it's
	// unknown to us.
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_PAYLOAD_UNKNOWN ConnectionLayerStatus = 16
	// The connection was reset
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_RESET ConnectionLayerStatus = 17
	// The connection timed out
	ConnectionLayerStatus_CONNECTION_LAYER_STATUS_TIMEOUT ConnectionLayerStatus = 18
)

